// Controls fall together when they trust the same secret.
const controls = [
  { name: 'pwd-screen-1', trusts: ['password'] },
  { name: 'pwd-screen-2', trusts: ['password'] },
  { name: 'camera', trusts: ['power'] },
  { name: 'alarm', trusts: ['power'] },
];
const leaked = 'password';
const fallen = controls.filter((c) => c.trusts.includes(leaked)).map((c) => c.name);
const survivors = controls.filter((c) => !c.trusts.includes(leaked)).map((c) => c.name);
console.log('fallen:' + fallen.join(','));
console.log('survivors:' + survivors.join(','));
